// expect: exit 0
// screen: 0 hello world 11
// screen: 1 h*llo
// screen: 2 hhelloworld
char s[20], t[20];
int main(void)
{
    cls();
    strcpy(s, "hello");
    strcat(s, " world");
    printf("%s %d\n", s, strlen(s));
    memcpy(t, s, 5);
    t[5] = 0;
    *strchr(t, 'e') = '*';
    printf("%s\n", t);
    memmove(s + 1, s, 5);
    printf("%s\n", s);
    memset(t, 'x', 3);
    if (memcmp(t, "xxxlo", 5))
        return 1;
    strncpy(t, "abc", 5);
    return strcmp(t, "abc") != 0 || strcmp("a", "b") >= 0;
}
